Controls {
  unsigned
      reserve_mode{}; // 0 legacy, 1 interval, 2 absorption, 3 twice interval.
  bool laying{true}, exchange{true}, positive{};
  std::int64_t absorption_hours{6}, behavior_hours{6}, reproduction_days{2};
